import{_ as s,l,o as a,c as i,v as o,p as n,x as r,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const x=JSON.parse('{"title":"宏与卫生","description":"","frontmatter":{"title":"宏与卫生","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/macros-hygiene.md","filePath":"cs/macros-hygiene.md","lastUpdated":1789023840000}'),h={name:"cs/macros-hygiene.md"};function m(u,e,_,f,E,b){const t=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="宏与卫生" tabindex="-1">宏与卫生 <a class="header-anchor" href="#宏与卫生" aria-label="Permalink to &quot;宏与卫生&quot;">​</a></h1><div class="epigraph"><p>宏是编译期的树或记号改写。不卫生的展开会捕获用户的名字；卫生宏用颜色或换名保证绑定结构不被偷偷改写。</p><footer>—— 据 Kohlbecker, Friedman, Felleisen and Duba, Hygienic Macro Expansion, 1986；Clinger and Rees, Macros That Work, 1991 整理</footer></div><p>上一课<a href="/cs/syntax-directed-translation">语法制导翻译</a>假定记号流已是语言本身。缺口是<strong>用户可定义的改写</strong>：Scheme 的 <code>syntax-rules</code>、Rust 的 <code>macro_rules</code>、模板元编程的边缘。本课钉捕获与卫生，不把 C 预处理器的全部坑写完——那是下一课。也不重写 λ 的 α 换名，只引用：<a href="/cs/lambda-calculus">λ 演算</a>里捕获会绑错，宏展开是同一事故的编译期版。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>非卫生：宏体里的 <code>tmp</code> 若与调用处的 <code>tmp</code> 同名，展开后绑到用户变量。卫生：宏引入的绑定带「颜色」，与用户标识符即使字符串相同也不冲突；用户传入的表达式在展开后仍绑到用户的环境。缺口是<strong>展开算法的换名不变量</strong>，不是再讲 SDT 的 <code>emit</code>。</p><p>对比函数：函数调用有求值规则与作用域；宏先改写再分析。把宏当函数会漏掉二次扫描与卫生。</p><h3 id="卫生不是「不能写坏宏」" tabindex="-1">卫生不是「不能写坏宏」 <a class="header-anchor" href="#卫生不是「不能写坏宏」" aria-label="Permalink to &quot;卫生不是「不能写坏宏」&quot;">​</a></h3><p>卫生防捕获；不防宏发出类型错误或指数大的代码。也不是卫生就不能故意 <code>unhygienic</code> 插入——部分语言提供逃逸，须显式。</p><p><span class="marginnote">Kohlbecker et al. 1986；Clinger–Rees 1991。Dybvig 的语法对象是工程标准参考。本课不进 typed template Haskell 的论文细节。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记号宏：替换列表，几乎必不卫生（C）。卫生宏：解析成语法对象，带词法上下文，展开时 <code>gensym</code> 或着色。模式匹配宏（<code>syntax-rules</code>）默认卫生；过程宏（<code>syntax-case</code>）要人遵守 API。</p>',11)),(a(),n(p,null,{default:r(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20CALL%5B%22%E5%AE%8F%E8%B0%83%E7%94%A8%22%5D%20--%3E%20EXP%5B%22%E5%B1%95%E5%BC%80%22%5D%0A%20%20EXP%20--%3E%20COL%5B%22%E7%9D%80%E8%89%B2%20%2F%20gensym%22%5D%0A%20%20COL%20--%3E%20RE%5B%22%E5%86%8D%E5%88%86%E6%9E%90%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与增量解析：宏展开使「源区间」映射变复杂，错误信息要指向调用处而非只指向展开后。接<a href="/cs/parse-error-recovery">错误恢复</a> 的诊断契约。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>多次展开直到没有宏调用（或达上限）。递归宏须终止；语言用进度检查或深度帽。卫生保证的是绑定结构，不保证与手工 α 换名后的项在类型上一律等价——那要另外的宏类型系统，本课点名。</p><p>不要用宏模拟模块系统的全部封装；卫生不是隐私。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 C 的 <code>#define</code> 扫描器。后课默认：卫生宏 = 展开不捕获；记号粘贴是另一家族。下一课 C 预处理器：故意不卫生、在词法阶段工作。</p><p>也不把 Rust 过程宏的编译器插件安全模型写完。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>宏是改写；捕获是 α 事故。</li><li>卫生用颜色或换名保住绑定。</li><li>记号宏（C）默认不卫生。</li><li>出处：Kohlbecker et al., 1986；Clinger and Rees, 1991。</li></ul>',9))])}const C=s(h,[["render",m]]);export{x as __pageData,C as default};
